/* Existing image tools are available from the selected asset, without changing other layers. */
let vectorTrace=null,vectorAsset=null,vectorBlob=null,vectorURL=null;import('./vector-trace.js?v=depot-v17').then(m=>vectorTrace=m.tracePalette);
const vectorDialog=document.createElement('dialog');vectorDialog.className='studioDialog';vectorDialog.innerHTML='<div class="studioHead"><h2>Vectorize image</h2><button class="pill" id="closeVector">Done</button></div><p class="sub">Local palette tracing creates editable SVG paths. Best for silhouettes, logos and poster styles. Photographs become a simplified mosaic; this is not a smooth illustration reconstruction.</p><div class="workLayout"><div><img id="vectorPreview" alt="SVG vector preview" style="width:100%;max-height:60vh;object-fit:contain"></div><aside><label>Detail (longest edge)<input id="vectorDetail" type="number" min="48" max="384" step="16" value="192"></label><label>Color levels per channel<input id="vectorLevels" type="number" min="2" max="8" value="4"></label><button class="pill wide" id="traceVector">Update preview</button><button class="pill wide" id="saveVector">Save new SVG asset</button><button class="primary wide" id="applyVector">Use on selected asset</button><p class="sub" id="vectorStatus"></p></aside></div>';document.body.append(vectorDialog);
function openVectorTool(id){vectorAsset=id;vectorBlob=null;vectorDialog.showModal();paintVector()}
async function paintVector(){const im=getStudioMedia(vectorAsset),status=vectorDialog.querySelector('#vectorStatus');if(!vectorTrace){status.textContent='Vector tracer is loading…';return}if(!mediaIsReady(im)){im?.addEventListener('load',paintVector,{once:true});return}try{const detail=Math.max(48,Math.min(384,+vectorDialog.querySelector('#vectorDetail').value||192)),r=detail/Math.max(im.naturalWidth,im.naturalHeight),c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.naturalWidth*r));c.height=Math.max(1,Math.round(im.naturalHeight*r));const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(im,0,0,c.width,c.height);const svg=vectorTrace(ctx.getImageData(0,0,c.width,c.height).data,c.width,c.height,+vectorDialog.querySelector('#vectorLevels').value);vectorBlob=new Blob([svg],{type:'image/svg+xml'});if(vectorURL)URL.revokeObjectURL(vectorURL);vectorURL=URL.createObjectURL(vectorBlob);vectorDialog.querySelector('#vectorPreview').src=vectorURL;status.textContent=c.width+' × '+c.height+' path grid · '+Math.round(vectorBlob.size/1024)+' KB · transparency preserved'}catch(e){status.textContent='Could not read this image: '+e.message}}
vectorDialog.querySelector('#closeVector').onclick=()=>vectorDialog.close();vectorDialog.querySelector('#traceVector').onclick=paintVector;vectorDialog.querySelector('#saveVector').onclick=async()=>{if(!vectorBlob)return;await storeStudioAsset(new File([vectorBlob],'vectorized.svg',{type:'image/svg+xml'}),null,{method:'local palette-traced SVG paths',parentId:vectorAsset,alpha:true});vectorDialog.querySelector('#vectorStatus').textContent='Saved new SVG in Assets & recipes. Original preserved.'};vectorDialog.querySelector('#applyVector').onclick=async()=>{if(!vectorBlob)return;await storeStudioAsset(new File([vectorBlob],'vectorized.svg',{type:'image/svg+xml'}),vectorAsset,{method:'local palette-traced SVG paths'});vectorDialog.close();assetSave()};
const applyCutout=document.createElement('button');applyCutout.className='primary';applyCutout.id='applyCutoutToAsset';applyCutout.textContent='Apply to selected asset';cutDialog.querySelector('.studioActions').append(applyCutout);applyCutout.onclick=()=>{if(cutPoints.length<3){cutDialog.querySelector('#cutoutStatus').textContent='Trace at least three points around the subject first.';return}const canvas=makeCutout(getStudioMedia(cutAsset));canvas.toBlob(async blob=>{if(!blob)return;await storeStudioAsset(new File([blob],'cutout.png',{type:'image/png'}),cutAsset,{method:'manual polygon alpha mask'});cutDialog.close();assetSave()})};
